package com.mooncast.unified;

import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import java.io.*;import java.util.concurrent.*;import java.util.regex.*;

/** Real control-window measurement and injected gestures. Session callbacks are synthetic. */
public final class ControlsLayoutDeviceTest {
 private final Instrumentation runner;private volatile Messenger endpoint;private int nonce;
 private final ConcurrentHashMap<Integer,CompletableFuture<Bundle>> replies=new ConcurrentHashMap<>();
 private final Messenger reply=new Messenger(new Handler(Looper.getMainLooper(),message->{CompletableFuture<Bundle> f=replies.remove(message.getData().getInt("nonce"));if(f!=null)f.complete(message.getData());return true;}));
 public ControlsLayoutDeviceTest(Instrumentation runner){this.runner=runner;}
 public void run(){Context context=runner.getTargetContext();Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;StringBuilder evidence=new StringBuilder();String size=null,density=null,font=null,op=null;float originalFontScale=context.getResources().getConfiguration().fontScale;Activity activity=null;ServiceConnection binding=null;Intent service=new Intent().setClassName(context.getPackageName(),"com.mooncast.host.ControlsFixtureService");
  try{
   require(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"disposable emulator only");
   size=override(shell("wm size"));density=override(shell("wm density"));font=shell("settings get system font_scale").trim();op=overlayMode(context.getPackageName());
   shell("appops set "+context.getPackageName()+" SYSTEM_ALERT_WINDOW allow");shell("wm size 480x600");shell("wm density 240");shell("settings put system font_scale 1.3");SystemClock.sleep(2000);
   activity=runner.startActivitySync(new Intent(context,ControlsBackdropActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
   context.startService(service);CountDownLatch ready=new CountDownLatch(1);binding=new ServiceConnection(){public void onServiceConnected(ComponentName name,IBinder binder){endpoint=new Messenger(binder);ready.countDown();}public void onServiceDisconnected(ComponentName name){endpoint=null;}};
   require(context.bindService(service,binding,Context.BIND_AUTO_CREATE)&&ready.await(15,TimeUnit.SECONDS),"real controls owner binds");
   Bundle state=waitVisible("controls_bubble");int owner=state.getInt("pid"),instance=state.getInt("instance");require(Math.abs(state.getInt("screenWidth")/state.getFloat("density")-320)<2,"320dp viewport");require(Math.abs(state.getFloat("fontScale")-1.3f)<.02f,"large-font resources applied");tap((Rect)state.getParcelable("controls_bubble"));state=waitVisible("ui_stop");inside(state,"ui_stop");Rect scroll=state.getParcelable("scroll");require(state.getInt("scrollContent")>state.getInt("scrollViewport"),"overflowing controls fixture");int initialScroll=state.getInt("scrollY");swipe(scroll,true);state=waitVisible("ui_stop");inside(state,"ui_stop");int scrolled=state.getInt("scrollY");require(scrolled>initialScroll,"actual upward gesture scrolls operation content");swipe(scroll,false);state=waitVisible("ui_stop");require(state.getInt("scrollY")<scrolled,"actual downward gesture scrolls operation content back");
   state=waitVisible("controls_pause");tap((Rect)state.getParcelable("controls_pause"));state=waitVisible("controls_resume");require(state.getBoolean("paused")&&state.getInt("pauseCommands")==1,"pause command reached session once");tap((Rect)state.getParcelable("controls_resume"));state=waitVisible("controls_pause");require(!state.getBoolean("paused")&&state.getInt("pauseCommands")==2,"resume command reached session once");
   evidence.append("320dp / font1.3: expanded Stop fully visible during verified content scrolling; real taps dispatched Pause and Resume\n");
   // Preserve the same production controls service through an actual display configuration change.
   shell("wm density 160");shell("wm size 800x480");SystemClock.sleep(2000);state=waitVisible("ui_stop");require(state.getInt("screenWidth")>state.getInt("screenHeight"),"landscape resources applied");inside(state,"ui_stop");require(state.getInt("pid")==owner&&state.getInt("instance")==instance,"same controls owner survives configuration change");
   Rect bubble=state.getParcelable("controls_collapse");drag(bubble,state.getInt("screenWidth")-12,state.getInt("screenHeight")-12);state=waitVisible("ui_stop");inside(state,"ui_stop");tap((Rect)state.getParcelable("controls_collapse"));state=waitVisible("controls_bubble");inside(state,"controls_bubble");tap((Rect)state.getParcelable("controls_bubble"));state=waitVisible("ui_stop");inside(state,"ui_stop");
   evidence.append("landscape/reposition/collapse/re-expand: Stop and bubble remain fully visible\n");tap((Rect)state.getParcelable("ui_stop"));long end=SystemClock.elapsedRealtime()+5000;do{state=query(0);if(!state.getBoolean("overlay"))break;SystemClock.sleep(100);}while(SystemClock.elapsedRealtime()<end);require(state.getBoolean("stopped")&&!state.getBoolean("overlay"),"actual Stop tap retires controls window");code=Activity.RESULT_OK;
  }catch(Throwable failure){evidence.append(android.util.Log.getStackTraceString(failure));}
  finally{
   try{if(endpoint!=null)query(2);}catch(Throwable failure){code=Activity.RESULT_CANCELED;evidence.append("Control close: ").append(failure).append('\n');}
   if(binding!=null)try{context.unbindService(binding);}catch(Throwable failure){code=Activity.RESULT_CANCELED;evidence.append("Unbind: ").append(failure).append('\n');}
   try{context.stopService(service);}catch(Throwable failure){code=Activity.RESULT_CANCELED;evidence.append("Service cleanup: ").append(failure).append('\n');}
   if(activity!=null)try{Activity old=activity;runner.runOnMainSync(old::finish);}catch(Throwable failure){code=Activity.RESULT_CANCELED;evidence.append("Activity cleanup: ").append(failure).append('\n');}
   try{if(size!=null){shell("wm size "+size);require(size.equals(override(shell("wm size"))),"display size restored");}}catch(Throwable failure){code=Activity.RESULT_CANCELED;evidence.append("Size cleanup: ").append(failure).append('\n');}
   try{if(density!=null){shell("wm density "+density);require(density.equals(override(shell("wm density"))),"density restored");}}catch(Throwable failure){code=Activity.RESULT_CANCELED;evidence.append("Density cleanup: ").append(failure).append('\n');}
   try{if(font!=null){shell(font.equals("null")?"settings delete system font_scale":"settings put system font_scale "+font);String restored=shell("settings get system font_scale").trim();evidence.append("Font restore original=").append(font).append(" actual=").append(restored).append(" resourceBaseline=").append(originalFontScale).append('\n');require(restored.equals(font)||(!restored.equals("null")&&Math.abs(Float.parseFloat(restored)-originalFontScale)<.001f),"font restored to original effective scale");}}catch(Throwable failure){code=Activity.RESULT_CANCELED;evidence.append("Font cleanup: ").append(failure).append('\n');}
   try{if(op!=null){shell("appops set "+context.getPackageName()+" SYSTEM_ALERT_WINDOW "+op);require(op.equals(overlayMode(context.getPackageName())),"overlay mode restored");}}catch(Throwable failure){code=Activity.RESULT_CANCELED;evidence.append("Overlay cleanup: ").append(failure).append('\n');}
  }
  result.putString("stream",(code==Activity.RESULT_OK?"CONTROLS_LAYOUT_DEVICE_PASSED\n":"CONTROLS_LAYOUT_DEVICE_FAILED\n")+evidence+"Scope: actual control-window geometry/gestures and synthetic session command dispatch; not real casting or physical-panel validation\n");runner.finish(code,result);
 }
 private Bundle query(int what)throws Exception{Messenger target=endpoint;require(target!=null,"control endpoint alive");int token=++nonce;CompletableFuture<Bundle> pending=new CompletableFuture<>();replies.put(token,pending);Message message=Message.obtain();message.what=what;message.replyTo=reply;Bundle data=new Bundle();data.putInt("nonce",token);message.setData(data);target.send(message);try{Bundle result=pending.get(5,TimeUnit.SECONDS);require(!result.containsKey("failure"),"service failure "+result.getString("failure"));return result;}finally{replies.remove(token);}}
 private Bundle waitVisible(String key)throws Exception{long end=SystemClock.elapsedRealtime()+15000;Bundle state=null;while(SystemClock.elapsedRealtime()<end){state=query(0);if(state.getBoolean(key+"Visible"))return state;SystemClock.sleep(100);}throw new AssertionError("control fully visible: "+key+" state="+state);}
 private void inside(Bundle state,String key){Rect r=state.getParcelable(key);require(r!=null&&r.left>=0&&r.top>=0&&r.right<=state.getInt("screenWidth")&&r.bottom<=state.getInt("screenHeight"),"control within physical viewport: "+key+" "+r);}
 private void tap(Rect r){require(r!=null,"real control rectangle");long down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,r.exactCenterX(),r.exactCenterY());touch(down,MotionEvent.ACTION_UP,r.exactCenterX(),r.exactCenterY());SystemClock.sleep(250);}
 private void swipe(Rect r,boolean up){require(r!=null&&r.height()>80,"scrollable operation area");float x=r.exactCenterX(),from=r.top+r.height()*(up?.8f:.2f),to=r.top+r.height()*(up?.2f:.8f);long down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,x,from);for(int i=1;i<=8;i++){touch(down,MotionEvent.ACTION_MOVE,x,from+(to-from)*i/8);SystemClock.sleep(80);}touch(down,MotionEvent.ACTION_UP,x,to);SystemClock.sleep(400);}
 private void drag(Rect r,float x,float y){require(r!=null,"bubble rectangle");long down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,r.exactCenterX(),r.exactCenterY());for(int step=1;step<=8;step++){touch(down,MotionEvent.ACTION_MOVE,r.exactCenterX()+(x-r.exactCenterX())*step/8,r.exactCenterY()+(y-r.exactCenterY())*step/8);SystemClock.sleep(50);}touch(down,MotionEvent.ACTION_UP,x,y);SystemClock.sleep(300);}
 private void touch(long down,int action,float x,float y){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);require(runner.getUiAutomation().injectInputEvent(event,true),"injected real touch");event.recycle();}
 private String shell(String command)throws Exception{try(ParcelFileDescriptor descriptor=runner.getUiAutomation().executeShellCommand(command);InputStream input=new FileInputStream(descriptor.getFileDescriptor());ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] bytes=new byte[4096];int n;while((n=input.read(bytes))!=-1){output.write(bytes,0,n);require(output.size()<65536,"bounded shell output");}return output.toString("UTF-8");}}
 private static String override(String output){Matcher m=Pattern.compile("Override (?:size|density): ([0-9x]+)").matcher(output);return m.find()?m.group(1):"reset";}
 private String overlayMode(String pkg)throws Exception{String raw=shell("appops get "+pkg+" SYSTEM_ALERT_WINDOW");Matcher m=Pattern.compile("SYSTEM_ALERT_WINDOW: (allow|deny|ignore|default|foreground)").matcher(raw);if(m.find())return m.group(1);require(raw.contains("No operations"),"known AppOps mode");return "default";}
 private static void require(boolean yes,String why){if(!yes)throw new AssertionError(why);}
}
